"""The journal file: a whole book as readable text."""
import re
from dataclasses import dataclass, field
from fractions import Fraction
from typing import List

from .accounts import account_type, valid_path
from .currency import CURRENCIES
from .dates import DateError, format_date, parse_date
from .errors import ParseError, TallybookError
from .ledger import Ledger
from .model import Account, Posting, Transaction
from .money import Money


class JournalError(ParseError):
    def __init__(self, line, description=""):
        self.line = line
        self.description = description
        super().__init__("line %s: %s" % (line, description))

    def __reduce__(self):
        return (JournalError, (self.line, self.description))


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: List[tuple] = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for a in self.accounts:
            ledger.chart.add(a.path, a.type, a.currency, a.opened, a.note)
            if a.closed is not None:
                ledger.chart.close(a.path, a.closed)
        for src, dst, on, text in self.rates:
            ledger.rates.set(src, dst, text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# -- reading ------------------------------------------------------------

_BLANK = " \t"
_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")
_TAG_RE = re.compile(r"#[A-Za-z0-9][A-Za-z0-9_-]*")
_WORD, _QUOTED = "w", "q"


def _tokenize(line, no):
    """Split a line into ('w'|'q', text) tokens and the trailing comment (or None)."""
    tokens = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANK:
        raise JournalError(no, "amount '%s' needs a currency" % tokens[1][1])
    elif len(tokens) > 3:
        raise JournalError(no, "unexpected '%s' in posting" % tokens[3][1])
    note = comment.strip(_BLANK) if comment is not None else ""
    return Posting(account, amount, note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "journal must be text")
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.replace("\r\n", "\n").split("\n")
    journal = Journal()
    seen = set()
    current = None
    for no, line in enumerate(lines, 1):
        stripped = line.strip(_BLANK)
        if not stripped:
            current = None
            continue
        if stripped[0] in ";#":
            continue
        tokens, comment = _tokenize(line, no)
        if line[0] in _BLANK:
            if current is None:
                raise JournalError(no, "indented line outside a transaction")
            current.postings.append(_parse_posting(tokens, comment, no))
            continue
        current = None
        head = tokens[0] if tokens else None
        if head == (_WORD, "account"):
            journal.accounts.append(_parse_account(tokens, comment, no, seen))
        elif head == (_WORD, "rate"):
            journal.rates.append(_parse_rate(tokens, comment, no))
        else:
            current = _parse_tx_line(tokens, comment, no)
            journal.transactions.append(current)
    return journal


# -- writing ------------------------------------------------------------


def _quote(text):
    return '"' + str(text).replace("\\", "\\\\").replace('"', '\\"') + '"'
    def _range(self):
        """Index range [i0, i1) of the series in the schedule's own numbering."""
        sched = self.schedule
        i0 = sched._count_before(self.start.toordinal())
        i1 = sched._total()
        if self.end is not None:
            i1 = min(i1, sched._count_before(self.end.toordinal() + 1))
        if self.count is not None:
            i1 = min(i1, i0 + self.count)
        return i0, max(i0, i1)


def _need_recurring(rec):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: '%s'" % (rec,))


def _window(rec, start, end):
    _need_recurring(rec)
    _need_date(start, "start")
    _need_date(end, "end")
    if end < start:
        return range(0)
    i0, i1 = rec._range()
    lo = max(i0, rec.schedule._count_before(start.toordinal()))
    hi = min(i1, rec.schedule._count_before(end.toordinal() + 1))
    return range(lo, hi)


def occurrences(rec, start, end):
    window = _window(rec, start, end)
    return [rec.schedule._nth(i) for i in window]


def next_occurrence(rec, after):
    _need_recurring(rec)
    _need_date(after, "after")
    i0, i1 = rec._range()
    i = max(i0, rec.schedule._count_before(after.toordinal() + 1))
    return rec.schedule._nth(i) if i < i1 else None


def instantiate(rec, on):
    _need_recurring(rec)
    _need_date(on, "date")
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    if isinstance(recs, (str, bytes)) or not hasattr(recs, "__iter__"):
        raise RecurringError("recs must be a list of Recurring items")
    recs = list(recs)
    _need_date(start, "start")
    _need_date(end, "end")
    found = []
    for pos, rec in enumerate(recs):
        for on in occurrences(rec, start, end):
            found.append((on, rec.name, pos, rec))
    found.sort(key=lambda e: e[:3])
    return [instantiate(rec, on) for on, _, _, rec in found]


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        return "%dth" % n
    return "%d%s" % (n, {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th"))


def describe(schedule):
    if not isinstance(schedule, Schedule):
        raise RecurringError("not a schedule: '%s'" % (schedule,))
    k = schedule.kind
    if k == "daily":
        return "every day"
    if k == "weekly":
        return "every %s" % _WEEKDAY_NAMES[schedule.weekday]
    if k == "monthly":
        if schedule.day == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(schedule.day)
    if k == "yearly":
        return "every year on %d %s" % (schedule.day, _MONTH_NAMES[schedule.month - 1])
    if schedule.step == 1:
        return "every %s from %s" % (schedule.unit[:-1], format_date(schedule.anchor))
    return "every %d %s from %s" % (schedule.step, schedule.unit, format_date(schedule.anchor))
"""CSV bank-statement import driven by a small profile file."""
import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from .currency import CURRENCIES
from .errors import ParseError
from .model import Posting, Transaction
from .money import Money, MoneyError, parse_amount
from .rules import RuleSet, parse_rules, valid_account_path, valid_tag


class CsvImportError(ParseError):
    def __init__(self, message, line=None, detail=None):
        super().__init__(message, detail)
        self.line = line


@dataclass(frozen=True)
class ImportProfile:
    date_column: str
    payee_column: str
    currency: str
