    for key in ("account", "payee", "narration", "flag"):
        if key in won:
            ctx.line(_keyed(key, won[key]))
    if "tags" in won:
        ctx.line(_keyed("tags", ",".join(won["tags"])))


# ------------------------------------------------------------ journal files
@command("calc journal check", "check a journal file as a book", args="FILE")
def journal_check(ctx, a):
    journal, _ = _load_journal(ctx, a.args[0])
    journal.to_ledger()
