    kind, account = a.args
    if kind not in _REPORT_KINDS:
        raise UsageError("unknown report '%s'" % kind)
    if kind == "register" and account is None:
        raise UsageError("report register needs an ACCOUNT")
    ledger = _load_ledger(ctx, a.get("--journal"))
    convert = a.get("--convert")
    as_of = a.get("--as-of")
    period = a.get("--period")
    if kind == "trial-balance":
        report = reports.trial_balance(ledger, parse_date(as_of) if as_of is not None else None)
    elif kind == "balance-sheet":
        on = parse_date(as_of) if as_of is not None else ctx.today
        report = reports.balance_sheet(ledger, on, convert)
    elif kind in ("income-statement", "cashflow"):
        chosen = Period.parse(period) if period is not None else _month_of(ctx.today)
