    "calc report",
    "a report of a journal book",
    args="KIND [ACCOUNT]",
    options={
        "--journal": "FILE",
        "--as-of": "DATE",
        "--period": "PERIOD",
        "--convert": "CUR",
    },
    flags=("--rollup", "--json"),
    required=("--journal",),
)
def report_of(ctx, a):
    kind, account = a.args
    if kind not in _REPORT_KINDS:
        raise UsageError("unknown report '%s'" % kind)
    if kind == "register" and account is None:
        raise UsageError("report register needs an ACCOUNT")
    ledger = _load_ledger(ctx, a.get("--journal"))
    convert = a.get("--convert")
    as_of = a.get("--as-of")
    period = a.get("--period")
    if kind == "trial-balance":
        report = reports.trial_balance(ledger, parse_date(as_of) if as_of is not None else None)
    elif kind == "balance-sheet":
        on = parse_date(as_of) if as_of is not None else ctx.today
        report = reports.balance_sheet(ledger, on, convert)
    elif kind in ("income-statement", "cashflow"):
        chosen = Period.parse(period) if period is not None else _month_of(ctx.today)
        if kind == "cashflow":
            report = reports.cashflow(ledger, chosen)
        else:
            report = reports.income_statement(ledger, chosen, convert)
    else:
        chosen = Period.parse(period) if period is not None else None
        report = reports.register(ledger, account, chosen, a.flag("--rollup"))
    if a.flag("--json"):
        ctx.write(to_json(report))
    else:
        ctx.write(reports.render_text(report))


@command(
    "calc csv",
    "what importing a bank statement would produce",
    args="PROFILE_FILE CSV_FILE",
    options={"--rules": "FILE"},
)
def csv_journal(ctx, a):
    profile, _ = _read(ctx, a.args[0])
    statement, _ = _read(ctx, a.args[1])
    rules = _read(ctx, a.get("--rules"))[0] if a.get("--rules") is not None else None
    result = import_csv(statement, profile, rules)
    if result.errors:
        raise CliError(
            "%d rows could not be imported, nothing was imported" % len(result.errors),
            ["row %d: %s" % (number, message) for number, message in result.errors],
        )
    ctx.write(format_journal(Journal([], [], result.transactions)))
